<?php
require_once __DIR__ . '/../config/db.php';
$pageTitle='Proposals | Freelance Marketplace System'; $search=trim($_GET['search']??''); $successMsg=$_GET['success']??''; $errorMsg=$_GET['error']??'';
$query="SELECT p.proposal_id,p.cover_letter,p.bid_amount,p.date_submitted,p.status,p.freelancer_id,u.name AS freelancer_name,p.project_id,pr.title AS project_title FROM Proposal p INNER JOIN Freelancer f ON p.freelancer_id=f.freelancer_id INNER JOIN `User` u ON f.freelancer_id=u.user_id INNER JOIN Project pr ON p.project_id=pr.project_id WHERE 1=1"; $params=[]; $types=''; if($search!==''){$query.=" AND (u.name LIKE ? OR pr.title LIKE ? OR p.cover_letter LIKE ?)"; $like='%'.$search.'%'; $params=[$like,$like,$like]; $types='sss';} $query.=" ORDER BY p.proposal_id"; if($params){$stmt=$conn->prepare($query); $stmt->bind_param($types,...$params); $stmt->execute(); $proposals=$stmt->get_result();}else{$proposals=$conn->query($query);} include __DIR__ . '/../includes/header.php'; include __DIR__ . '/../includes/navbar.php';
?>
<section class="table-card"><div class="section-heading"><div><span class="eyebrow">Proposal Records</span><h2 class="page-title">Proposals</h2><p class="page-intro">All proposals submitted by freelancers for projects.</p></div><div class="section-actions"><a class="btn" href="<?php echo $basePath; ?>/pages/add_proposal.php">+ Add Proposal</a></div></div><?php if($successMsg!==''):?><div class="message success"><?php echo htmlspecialchars($successMsg); ?></div><?php endif;?><?php if($errorMsg!==''):?><div class="message error"><?php echo htmlspecialchars($errorMsg); ?></div><?php endif;?><form method="GET" action="" class="search-bar" style="display:flex;"><input type="text" name="search" placeholder="Search by freelancer, project, or cover letter..." value="<?php echo htmlspecialchars($search); ?>"><button type="submit" class="btn btn-secondary">Search</button><?php if($search!==''):?><a href="<?php echo $basePath; ?>/pages/proposals.php" class="btn btn-secondary">Clear</a><?php endif;?></form><div class="table-wrapper"><table class="data-table proposals-table"><thead><tr><th>ID</th><th>Freelancer</th><th>Project</th><th>Bid Amount</th><th>Status</th><th>Date</th><th>Cover Letter</th><th>Actions</th></tr></thead><tbody><?php if($proposals&&$proposals->num_rows>0): while($row=$proposals->fetch_assoc()):?><tr><td class="col-id"><?php echo $row['proposal_id']; ?></td><td class="col-name"><?php echo htmlspecialchars($row['freelancer_name']); ?> (ID: <?php echo $row['freelancer_id']; ?>)</td><td class="col-title"><?php echo htmlspecialchars($row['project_title']); ?> (ID: <?php echo $row['project_id']; ?>)</td><td class="col-money">$<?php echo number_format((float)$row['bid_amount'],2); ?></td><td class="col-status"><span class="badge badge-<?php echo strtolower($row['status']); ?>"><?php echo htmlspecialchars($row['status']); ?></span></td><td class="col-date"><?php echo htmlspecialchars($row['date_submitted']); ?></td><td class="col-description"><?php echo htmlspecialchars($row['cover_letter'] ?? ''); ?></td><td class="col-actions"><div class="btn-group"><a class="btn btn-sm btn-secondary" href="<?php echo $basePath; ?>/pages/edit_proposal.php?id=<?php echo $row['proposal_id']; ?>">Edit</a><a class="btn btn-sm btn-danger" href="<?php echo $basePath; ?>/pages/delete_proposal.php?id=<?php echo $row['proposal_id']; ?>" onclick="return confirm('Are you sure you want to delete this proposal? Related contracts will also be deleted.');">Delete</a></div></td></tr><?php endwhile; else:?><tr><td colspan="8"><div class="empty-state"><p>No proposals found.</p><a class="btn" href="<?php echo $basePath; ?>/pages/add_proposal.php">Add the first proposal</a></div></td></tr><?php endif;?></tbody></table></div></section><?php include __DIR__ . '/../includes/footer.php'; $conn->close(); ?>
